import React, { useState, useEffect } from "react";

export default function SafetyCheck({ tourist }) {
  const [latitude, setLatitude] = useState("");
  const [longitude, setLongitude] = useState("");
  const [result, setResult] = useState("");
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    // try auto-fetching once on load
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setLatitude(position.coords.latitude.toFixed(4));
          setLongitude(position.coords.longitude.toFixed(4));
        },
        () => {
          // ignore
        }
      );
    }
  }, []);

  const handleFetchLocation = () => {
    if (!navigator.geolocation) {
      alert("Geolocation not supported by your browser.");
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        setLatitude(pos.coords.latitude.toFixed(4));
        setLongitude(pos.coords.longitude.toFixed(4));
      },
      (err) => {
        console.error(err);
        alert("Allow location access.");
      }
    );
  };

  const handleCheckSafety = async () => {
    if (!latitude || !longitude) {
      alert("Please enter or fetch your location first!");
      return;
    }
    try {
      setLoading(true);
      const resp = await fetch("http://localhost:5000/api/safety/check", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ latitude: parseFloat(latitude), longitude: parseFloat(longitude) }),
      });
      const data = await resp.json();
      setResult(data.message);
    } catch (err) {
      console.error(err);
      setResult("Error checking safety");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={rootStyle}>
      <div style={cardStyle}>
        <h2 style={{ color: "#ff6f00", marginBottom: 10 }}>Welcome, {tourist?.name || "Traveler"} 🌏</h2>
        <p style={{ color: "#777", marginBottom: 12 }}>Your Block ID: <strong>{tourist?.blockId}</strong></p>

        <div style={{ marginBottom: 12 }}>
          <button onClick={handleFetchLocation} style={btnPrimary}>📍 Fetch My Location</button>
          <button onClick={handleCheckSafety} style={btnSecondary}>{loading ? "Checking..." : "🔒 Check Safety"}</button>
        </div>

        <div style={{ marginTop: 8 }}>
          <p><strong>Latitude:</strong> {latitude || "Not available"}</p>
          <p><strong>Longitude:</strong> {longitude || "Not available"}</p>
        </div>

        {result && (
          <div style={{ marginTop: 14, padding: 10, borderRadius: 8, background: result.toLowerCase().includes("safe") ? "#e6ffed" : "#ffe6e6" }}>
            <strong>{result}</strong>
          </div>
        )}
      </div>
    </div>
  );
}

const rootStyle = {
  minHeight: "100vh",
  display: "flex",
  justifyContent: "center",
  alignItems: "center",
  background:
    "linear-gradient(135deg, rgba(255,156,66,0.9), rgba(255,111,0,0.85))",
  fontFamily: "'Poppins', sans-serif",
  padding: 20,
};

const cardStyle = {
  backgroundColor: "white",
  padding: 28,
  borderRadius: 18,
  boxShadow: "0 10px 30px rgba(0,0,0,0.18)",
  width: 420,
  maxWidth: "95%",
  textAlign: "center",
};

const btnPrimary = {
  background: "#22c55e",
  color: "white",
  border: "none",
  padding: "10px 14px",
  borderRadius: 8,
  cursor: "pointer",
  marginRight: 8,
};

const btnSecondary = {
  background: "#ff6f00",
  color: "white",
  border: "none",
  padding: "10px 14px",
  borderRadius: 8,
  cursor: "pointer",
};
